UPDATE companies SET description='Victory Metal Works operates from Scottsdale, Arizona, where it has served the Phoenix metropolitan area for over 25 years. The company fabricates custom architectural iron and steel products from its facility at 8350 E. Evans Road, Suite B2, handling design, fabrication, and installation under one roof.

The shop specializes in custom iron entry doors — single, double, sidelight, transom, wine cellar, and modern styles — as well as gates, railings, fencing, balconies, and ornamental metal sculptures. All fabrication is performed in-house using steel and wrought iron, with finishes typically consisting of acrylic paint. Typical lead times for custom pieces run eight to ten weeks from design approval to installation.

Victory Metal Works serves residential and commercial clients across Scottsdale, Paradise Valley, and the greater Phoenix region. Its customers include homeowners, builders, and architects seeking custom architectural metalwork for luxury homes and commercial properties.

The company emphasizes a service-first approach, citing its decades of experience and a commitment to exacting craftsmanship, detail, and style as the foundation of its reputation. Free quotes and on-site consultations are offered to ensure each project meets the client''s vision.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom iron entry door fabrication", "Metal gate fabrication", "Metal railing fabrication", "Architectural metal fabrication", "Custom metal fabrication", "Installation of fabricated products", "Design services", "Finishing (acrylic paint)", "Glass element integration", "Hardware fabrication"], "industries": ["Residential", "Commercial", "Architectural metalwork"], "materials": ["Steel", "Wrought iron", "Glass", "Acrylic paint"], "equipment": [], "volume": "", "lead_time": "8-10 weeks for custom products", "tolerances": "", "built_on": ["Over 25 years of experience in custom iron fabrication", "All steel and iron products fabricated in-house in Scottsdale, AZ", "Service-first approach with free quotes and on-site consultations", "Design-to-installation capability for doors, gates, railings, and architectural metalwork", "Typical lead times of 8\u201310 weeks for custom projects"], "facts_used": ["Location: Scottsdale, AZ -> db", "Over 25 years experience -> /", "Fabricates custom iron entry doors, gates, railings, architectural metalwork -> /", "All products fabricated in Scottsdale, AZ -> /", "Lead times 8-10 weeks -> /", "Materials: steel, wrought iron, acrylic paint -> /", "Service is number one priority -> /", "Serves Phoenix metro area -> /", "Company type: manufacturer -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Victory Metal Works designs, builds and installs high-end luxury custom iron entry doors", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now()