UPDATE companies SET description='Wheatstate Wood Design, LLC is based in Hesston, Kansas. The company manufactures face-frame cabinetry and a range of handcrafted furniture including silverware buffets, dining tables, glider rockers, chairs, and outdoor furniture. Cabinets are built to custom specifications with a selection of premium wood species and finish options, and all pieces are produced using traditional woodworking methods. The business serves residential customers seeking custom cabinetry and furniture, though specific industry sectors or client names are not disclosed. Wheatstate Wood Design emphasizes a commitment to exceptional craftsmanship and standing behind its work, aiming to exceed customer expectations on every project.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Face frame cabinet manufacturing", "Custom furniture manufacturing", "Wood finishing", "Custom wood species selection", "Handcrafted assembly"], "industries": [], "materials": ["Wood (premium species)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom face-frame cabinetry built to specification", "Handcrafted furniture including buffets, tables, rockers, chairs, and outdoor pieces", "Selection of premium wood species and custom finish options", "Commitment to exceptional craftsmanship and customer satisfaction"], "facts_used": ["Company name: Wheatstate Wood Design, LLC -> db", "Location: Hesston, Kansas -> db", "Products: face frame cabinets, silverware buffets, dining tables, glider rockers, chairs, outdoor furniture -> page \"/\"", "Custom specifications, premium wood species, custom finish options -> page \"/\"", "Handcrafted construction -> page \"/\"", "Mission: commitment to exceptional craftsmanship and customer satisfaction -> page \"/\""], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We offer expertly crafted face frame cabinets designed to your specifications.", "founded_year": "", "employe